import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const dbPath = process.env.DB_PATH || './data/workboard.sqlite';
if (dbPath !== ':memory:') mkdirSync(dirname(resolve(dbPath)), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
db.exec(`PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
)`);
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
const listTasks = db.prepare('SELECT id, project_id, title, completed, priority FROM tasks WHERE project_id = ? ORDER BY id');
const findTask = db.prepare('SELECT id, project_id, title, completed, priority FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const prioritizeTask = db.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const taskJson = task => ({ ...task, completed: Boolean(task.completed) });
const projectSelect = `SELECT p.id, p.name, p.archived,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id) AS total,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1) AS completed
  FROM projects p`;
const listProjects = db.prepare(`${projectSelect} ORDER BY p.id`);
const findProject = db.prepare(`${projectSelect} WHERE p.id = ?`);
const archiveProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const page = readFileSync(new URL('./public/index.html', import.meta.url));
const script = readFileSync(new URL('./public/app.js', import.meta.url));
const styles = readFileSync(new URL('./public/style.css', import.meta.url));

function send(res, status, body, type = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store' });
  res.end(type.startsWith('application/json') ? JSON.stringify(body) : body);
}

const server = http.createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && path === '/health') return send(res, 200, { status: 'ok' });
    if (req.method === 'GET' && path === '/api/projects') return send(res, 200, listProjects.all());
    const match = path.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && match) {
      const project = findProject.get(match[1]);
      return project ? send(res, 200, project) : send(res, 404, { error: 'Project not found' });
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks$/);
    const taskMatch = path.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
    if (req.method === 'GET' && tasksMatch) {
      if (!findProject.get(tasksMatch[1])) return send(res, 404, { error: 'Project not found' });
      return send(res, 200, listTasks.all(tasksMatch[1]).map(taskJson));
    }
    if ((req.method === 'POST' && (path === '/api/projects' || tasksMatch)) ||
        (req.method === 'PATCH' && (taskMatch || match))) {
      let body = '';
      for await (const chunk of req) {
        body += chunk;
        if (Buffer.byteLength(body) > 65536) return send(res, 413, { error: 'Request too large' });
      }
      let input;
      try { input = JSON.parse(body); }
      catch { return send(res, 400, { error: 'Invalid JSON' }); }
      if (req.method === 'PATCH' && match) {
        const project = findProject.get(match[1]);
        if (!project) return send(res, 404, { error: 'Project not found' });
        if (input && Object.hasOwn(input, 'name')) {
          if (project.archived) return send(res, 409, { error: 'Archived project' });
          const name = typeof input.name === 'string' ? input.name.trim() : '';
          if (!name) return send(res, 400, { error: 'Project name is required' });
          renameProject.run(name, match[1]);
        } else {
          if (typeof input?.archived !== 'boolean') return send(res, 400, { error: 'Archived must be a boolean' });
          archiveProject.run(Number(input.archived), match[1]);
        }
        return send(res, 200, findProject.get(match[1]));
      }
      if (tasksMatch) {
        const project = findProject.get(tasksMatch[1]);
        if (!project) return send(res, 404, { error: 'Project not found' });
        if (project.archived) return send(res, 409, { error: 'Archived project' });
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return send(res, 400, { error: 'Task title is required' });
        const result = insertTask.run(tasksMatch[1], title);
        return send(res, 201, taskJson(findTask.get(tasksMatch[1], result.lastInsertRowid)));
      }
      if (taskMatch) {
        if (!findTask.get(taskMatch[1], taskMatch[2])) return send(res, 404, { error: 'Task not found' });
        if (findProject.get(taskMatch[1]).archived) return send(res, 409, { error: 'Archived project' });
        if (input && Object.hasOwn(input, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return send(res, 400, { error: 'Task title is required' });
          renameTask.run(title, taskMatch[1], taskMatch[2]);
        } else if (input && Object.hasOwn(input, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return send(res, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          prioritizeTask.run(input.priority, taskMatch[1], taskMatch[2]);
        } else {
          if (typeof input?.completed !== 'boolean') return send(res, 400, { error: 'Completion must be a boolean' });
          updateTask.run(Number(input.completed), taskMatch[1], taskMatch[2]);
        }
        return send(res, 200, taskJson(findTask.get(taskMatch[1], taskMatch[2])));
      }
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return send(res, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return send(res, 201, findProject.get(result.lastInsertRowid));
    }
    if (req.method === 'GET' && (path === '/' || /^\/projects\/\d+$/.test(path))) {
      return send(res, 200, page, 'text/html; charset=utf-8');
    }
    if (req.method === 'GET' && path === '/app.js') return send(res, 200, script, 'text/javascript; charset=utf-8');
    if (req.method === 'GET' && path === '/style.css') return send(res, 200, styles, 'text/css; charset=utf-8');
    send(res, 404, { error: 'Not found' });
  } catch (error) {
    console.error(error);
    if (!res.headersSent) send(res, 500, { error: 'Something went wrong' });
    else res.end();
  }
});
server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}

const app = document.querySelector('#app');

function element(tag, text) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  return node;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to load projects');
  return data;
}

function alertBox() {
  const alert = element('p');
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  app.append(alert);
  return alert;
}

async function showProjects() {
  app.replaceChildren(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  const create = element('button', 'Create project');
  create.type = 'submit';
  form.append(label, input, create);
  app.append(form);
  const alert = alertBox();
  const filterLabel = element('label', 'Project filter');
  filterLabel.htmlFor = 'project-filter';
  const filter = element('select');
  filter.id = 'project-filter';
  for (const name of ['Active', 'Archived']) {
    const option = element('option', name);
    option.value = name;
    filter.append(option);
  }
  app.append(filterLabel, filter);
  let projects = [];
  const list = element('section');
  list.setAttribute('aria-label', 'Projects');
  app.append(list);

  function render() {
    list.replaceChildren();
    for (const project of projects) {
      if (Boolean(project.archived) !== (filter.value === 'Archived')) continue;
      const row = element('div');
      row.className = 'project-row';
      row.dataset.testid = 'project-row';
      const open = element('button', 'Open project');
      open.type = 'button';
      open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
      const summary = element('span', `${project.completed}/${project.total} completed`);
      summary.dataset.testid = 'project-summary';
      const archive = element('button', project.archived ? 'Restore project' : 'Archive project');
      archive.type = 'button';
      archive.addEventListener('click', async () => {
        archive.disabled = true;
        alert.hidden = true;
        try {
          await request(`/api/projects/${project.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ archived: !project.archived }),
          });
          await refresh();
        } catch (error) { showError(error); }
        finally { archive.disabled = false; }
      });
      row.append(element('span', project.name), summary, open, archive);
      list.append(row);
    }
  }
  function showError(error) {
    alert.textContent = error.message;
    alert.hidden = false;
  }
  async function refresh() {
    projects = await request('/api/projects');
    render();
  }
  filter.addEventListener('change', render);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) return showError(new Error('Project name is required'));
    create.disabled = true;
    alert.hidden = true;
    try {
      await request('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      input.value = '';
      await refresh();
      input.focus();
    } catch (error) { showError(error); }
    finally { create.disabled = false; }
  });
  try { await refresh(); }
  catch (error) { showError(error); }
}

async function showProject(id) {
  app.replaceChildren();
  const back = element('button', 'Projects');
  back.type = 'button';
  back.addEventListener('click', () => { location.href = '/'; });
  app.append(back);
  const alert = alertBox();
  try {
    const project = await request(`/api/projects/${id}`);
    const heading = element('h1', project.name);
    app.prepend(heading);
    document.title = `${project.name} — Workboard`;
    if (project.archived) app.append(element('p', 'Archived project'));
    const renameForm = element('form');
    const renameLabel = element('label', 'New project name');
    renameLabel.htmlFor = 'new-project-name';
    const renameInput = element('input');
    renameInput.id = 'new-project-name';
    renameInput.type = 'text';
    renameInput.disabled = Boolean(project.archived);
    const rename = element('button', 'Rename project');
    rename.type = 'submit';
    rename.disabled = Boolean(project.archived);
    renameForm.append(renameLabel, renameInput, rename);
    app.append(renameForm);
    renameForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (project.archived) return;
      const name = renameInput.value.trim();
      if (!name) return showError(new Error('Project name is required'));
      rename.disabled = true;
      alert.hidden = true;
      try {
        const saved = await request(`/api/projects/${id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        project.name = saved.name;
        heading.textContent = saved.name;
        document.title = `${saved.name} — Workboard`;
        renameInput.value = '';
        renameInput.focus();
      } catch (error) { showError(error); }
      finally { rename.disabled = Boolean(project.archived); }
    });
    const form = element('form');
    const label = element('label', 'Task title');
    label.htmlFor = 'task-title';
    const input = element('input');
    input.id = 'task-title';
    input.type = 'text';
    const create = element('button', 'Create task');
    create.type = 'submit';
    create.disabled = Boolean(project.archived);
    form.append(label, input, create);
    const filterLabel = element('label', 'Task filter');
    filterLabel.htmlFor = 'task-filter';
    const filter = element('select');
    filter.id = 'task-filter';
    for (const name of ['All', 'Open', 'Completed']) {
      const option = element('option', name);
      option.value = name;
      filter.append(option);
    }
    const priorityFilterLabel = element('label', 'Priority filter');
    priorityFilterLabel.htmlFor = 'priority-filter';
    const priorityFilter = element('select');
    priorityFilter.id = 'priority-filter';
    for (const name of ['All', 'Low', 'Normal', 'High']) {
      const option = element('option', name);
      option.value = name;
      priorityFilter.append(option);
    }
    const list = element('section');
    list.setAttribute('aria-label', 'Tasks');
    app.append(form, filterLabel, filter, priorityFilterLabel, priorityFilter, list);
    let tasks = [];
    function showError(error) {
      alert.textContent = error.message;
      alert.hidden = false;
    }
    function render() {
      list.replaceChildren();
      for (const task of tasks) {
        if (filter.value === 'Open' && task.completed) continue;
        if (filter.value === 'Completed' && !task.completed) continue;
        if (priorityFilter.value !== 'All' && task.priority !== priorityFilter.value) continue;
        const row = element('div');
        row.className = 'task-row';
        row.dataset.testid = 'task-row';
        const checkbox = element('input');
        checkbox.type = 'checkbox';
        checkbox.checked = task.completed;
        checkbox.disabled = Boolean(project.archived);
        checkbox.setAttribute('aria-label', `Complete ${task.title}`);
        checkbox.addEventListener('change', async () => {
          checkbox.disabled = true;
          alert.hidden = true;
          try {
            const saved = await request(`/api/projects/${id}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ completed: checkbox.checked }),
            });
            task.completed = saved.completed;
            render();
          } catch (error) {
            checkbox.checked = task.completed;
            showError(error);
          } finally { checkbox.disabled = false; }
        });
        const titleText = element('span', task.title);
        const taskRenameForm = element('form');
        const taskRenameLabel = element('label', 'New task title');
        taskRenameLabel.htmlFor = `new-task-title-${task.id}`;
        const taskRenameInput = element('input');
        taskRenameInput.id = taskRenameLabel.htmlFor;
        taskRenameInput.type = 'text';
        taskRenameInput.disabled = Boolean(project.archived);
        const taskRename = element('button', 'Rename task');
        taskRename.type = 'submit';
        taskRename.disabled = Boolean(project.archived);
        taskRenameForm.append(taskRenameLabel, taskRenameInput, taskRename);
        taskRenameForm.addEventListener('submit', async (event) => {
          event.preventDefault();
          if (project.archived) return;
          const title = taskRenameInput.value.trim();
          if (!title) return showError(new Error('Task title is required'));
          taskRename.disabled = true;
          alert.hidden = true;
          try {
            const saved = await request(`/api/projects/${id}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ title }),
            });
            task.title = saved.title;
            titleText.textContent = saved.title;
            checkbox.setAttribute('aria-label', `Complete ${saved.title}`);
            taskRenameInput.value = '';
            taskRenameInput.focus();
          } catch (error) { showError(error); }
          finally { taskRename.disabled = Boolean(project.archived); }
        });
        const priorityLabel = element('label', 'Task priority');
        priorityLabel.htmlFor = `task-priority-${task.id}`;
        const priority = element('select');
        priority.id = priorityLabel.htmlFor;
        for (const name of ['Low', 'Normal', 'High']) {
          const option = element('option', name);
          option.value = name;
          priority.append(option);
        }
        priority.value = task.priority;
        priority.disabled = Boolean(project.archived);
        priority.addEventListener('change', async () => {
          priority.disabled = true;
          alert.hidden = true;
          try {
            const saved = await request(`/api/projects/${id}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ priority: priority.value }),
            });
            task.priority = saved.priority;
            render();
          } catch (error) { showError(error); }
          finally {
            priority.value = task.priority;
            priority.disabled = Boolean(project.archived);
          }
        });
        row.append(titleText, checkbox, taskRenameForm, priorityLabel, priority);
        list.append(row);
      }
    }
    filter.addEventListener('change', render);
    priorityFilter.addEventListener('change', render);
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (project.archived) return;
      const title = input.value.trim();
      if (!title) return showError(new Error('Task title is required'));
      create.disabled = true;
      alert.hidden = true;
      try {
        const task = await request(`/api/projects/${id}/tasks`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title }),
        });
        tasks.push(task);
        input.value = '';
        render();
        input.focus();
      } catch (error) { showError(error); }
      finally { create.disabled = false; }
    });
    tasks = await request(`/api/projects/${id}/tasks`);
    render();
  } catch (error) {
    alert.textContent = error.message;
    alert.hidden = false;
  }
}

const match = location.pathname.match(/^\/projects\/(\d+)$/);
if (match) showProject(match[1]);
else showProjects();
